#!/usr/bin/env bash
set -euo pipefail

# 1. Reconstruct lib/firebase_options.dart if it is gitignored in the CI/Vercel clone
if [ ! -f "lib/firebase_options.dart" ]; then
  if [ -n "${FIREBASE_OPTIONS_BASE64:-}" ]; then
    echo "Decoding lib/firebase_options.dart from FIREBASE_OPTIONS_BASE64..."
    echo "$FIREBASE_OPTIONS_BASE64" | base64 -d > lib/firebase_options.dart
  else
    echo "Generating lib/firebase_options.dart for web build..."
    WEB_API_KEY="${FIREBASE_WEB_API_KEY:-}"
    cat <<EOF > lib/firebase_options.dart
// Generated by scripts/vercel_build.sh
// ignore_for_file: type=lint
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      return web;
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return web;
      case TargetPlatform.iOS:
        return web;
      case TargetPlatform.macOS:
        return web;
      case TargetPlatform.windows:
        return web;
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not supported for this platform.',
        );
    }
  }

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: '$WEB_API_KEY',
    appId: '1:573580636358:web:3fb925347fb212c5c0e7c7',
    messagingSenderId: '573580636358',
    projectId: 'assist-interiors-d4889',
    authDomain: 'assist-interiors-d4889.firebaseapp.com',
    storageBucket: 'assist-interiors-d4889.firebasestorage.app',
    measurementId: 'G-ZJCQL2M42H',
  );
}
EOF
  fi
fi

# 2. Install or reuse Flutter SDK
if command -v flutter >/dev/null 2>&1; then
  FLUTTER_BIN="flutter"
else
  if [ ! -d "flutter" ]; then
    git clone https://github.com/flutter/flutter.git -b stable --depth 1
  fi
  FLUTTER_BIN="./flutter/bin/flutter"
fi

# 3. Build Flutter Web release bundle
"$FLUTTER_BIN" config --enable-web
"$FLUTTER_BIN" pub get
"$FLUTTER_BIN" build web --release
